import{_ as n,o as t,c as r,a2 as a}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"Kalender","description":"Einträge auf einem Kalenderblatt darstellen, mit Start- und optionalem Enddatum.","frontmatter":{"title":"Kalender","description":"Einträge auf einem Kalenderblatt darstellen, mit Start- und optionalem Enddatum."},"headers":[],"relativePath":"ansichten/kalender.md","filePath":"ansichten/kalender.md","lastUpdated":1786086174000}'),i={name:"ansichten/kalender.md"};function l(s,e,d,o,m,u){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="kalender" tabindex="-1">Kalender <a class="header-anchor" href="#kalender" aria-label="Permalink to &quot;Kalender&quot;">​</a></h1><p>Die <strong>Kalender</strong>-Ansicht zeigt Einträge auf einem Kalenderblatt, positioniert über ein Datumsfeld.</p><p>Die Oberfläche beschreibt sie als <em>Termine übersichtlich verwalten</em>.</p><p><strong>Geeignet für:</strong> Termine, Fristen, Belegungen, Urlaubsplanung, Redaktionspläne.</p><h2 id="voraussetzung-ein-datumsfeld" tabindex="-1">Voraussetzung: ein Datumsfeld <a class="header-anchor" href="#voraussetzung-ein-datumsfeld" aria-label="Permalink to &quot;Voraussetzung: ein Datumsfeld&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Ohne Datumsfeld kein Kalender</p><blockquote><p><em>Um einen Kalender zu sehen, muss Ihr Grid mindestens ein Datumsfeld besitzen.</em></p></blockquote><p>Fehlt eines, bietet ApptiveGrid an, direkt eines anzulegen (<em>Ein Datumsfeld erstellen</em>).</p></div><p>Geeignet sind die Spaltentypen <strong>Datum</strong> und <strong>Datum und Uhrzeit</strong>.</p><h2 id="kalender-anlegen" tabindex="-1">Kalender anlegen <a class="header-anchor" href="#kalender-anlegen" aria-label="Permalink to &quot;Kalender anlegen&quot;">​</a></h2><ol><li>Wählen Sie unter dem Grid <strong>Ansicht erstellen</strong>.</li><li>Wählen Sie <strong>Kalender</strong>.</li><li>Legen Sie unter <strong>Kalender Einstellungen</strong> das Datumsfeld fest.</li></ol><p>Der Dialog heißt <em>Datumsfeld für Ereignisse festlegen</em>:</p><blockquote><p><em>Welches Datumsfeld möchten Sie für diese Ansicht verwenden? Ihre Einträge werden auf der Grundlage der Daten in diesem Feld platziert.</em></p></blockquote><h2 id="zeitraum-statt-einzelnem-termin" tabindex="-1">Zeitraum statt einzelnem Termin <a class="header-anchor" href="#zeitraum-statt-einzelnem-termin" aria-label="Permalink to &quot;Zeitraum statt einzelnem Termin&quot;">​</a></h2><p>Der Dialog kennt zwei Felder:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Von</strong></td><td>Startdatum — bestimmt die Position</td></tr><tr><td><strong>Bis (optional)</strong></td><td>Enddatum — macht aus dem Termin einen Zeitraum</td></tr></tbody></table><p>Ohne <em>Bis</em> erscheint der Eintrag als einzelner Termin. Mit <em>Bis</em> zieht er sich über mehrere Tage.</p><div class="tip custom-block"><p class="custom-block-title">Zwei Felder für Zeiträume anlegen</p><p>Für Urlaube, Projektphasen oder Buchungen brauchen Sie <strong>zwei</strong> Datumsspalten im Grid — etwa <code>Beginn</code> und <code>Ende</code>. Legen Sie beide an, bevor Sie die Kalenderansicht konfigurieren, sonst steht <em>Bis</em> nicht zur Auswahl.</p></div><h2 id="darstellung-wechseln" tabindex="-1">Darstellung wechseln <a class="header-anchor" href="#darstellung-wechseln" aria-label="Permalink to &quot;Darstellung wechseln&quot;">​</a></h2><p>Drei Zeitraster:</p><ul><li><strong>Tag</strong></li><li><strong>Woche</strong></li><li><strong>Monat</strong></li></ul><p>Über <strong>Heute</strong> springen Sie zum aktuellen Datum zurück.</p><div class="tip custom-block"><p class="custom-block-title">Welches Raster wofür</p><p><em>Monat</em> für die Gesamtübersicht und Kapazitätsplanung. <em>Woche</em> für die operative Arbeit. <em>Tag</em> für Termine mit Uhrzeit — dort zahlt sich der Spaltentyp <em>Datum und Uhrzeit</em> aus, weil die Einträge nach Tageszeit sortiert erscheinen.</p></div><h2 id="termin-anlegen" tabindex="-1">Termin anlegen <a class="header-anchor" href="#termin-anlegen" aria-label="Permalink to &quot;Termin anlegen&quot;">​</a></h2><p>Über <strong>Neues Ereignis</strong> legen Sie einen Eintrag direkt aus dem Kalender an. Das gewählte Datum wird dabei übernommen.</p><p>Der Eintrag entsteht im zugrunde liegenden Grid — mit allen Feldern, auch denen, die im Kalender nicht sichtbar sind.</p><h2 id="filter-und-mehrere-kalender" tabindex="-1">Filter und mehrere Kalender <a class="header-anchor" href="#filter-und-mehrere-kalender" aria-label="Permalink to &quot;Filter und mehrere Kalender&quot;">​</a></h2><p>Filter wirken wie in jeder Ansicht.</p><div class="tip custom-block"><p class="custom-block-title">Mehrere Kalender auf denselben Daten</p><p>Statt einen überladenen Kalender zu pflegen, legen Sie mehrere Ansichten an: „Meine Termine&quot; mit <code>Zuständig</code> <code>ist</code> <code>angemeldeter Benutzer</code>, „Nur bestätigt&quot; mit einem Statusfilter, „Abgabetermine&quot; auf einem anderen Datumsfeld.</p><p>Jede Ansicht kann ein <strong>anderes</strong> Datumsfeld verwenden — dasselbe Grid lässt sich so nach Beginn <em>und</em> nach Fälligkeit betrachten.</p></div><p>→ <a href="/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/ansichten/was-ist-eine-ansicht">Was ist eine Ansicht</a></li><li><a href="/ansichten/timeline">Timeline</a> — für Zeiträume über lange Strecken</li><li><a href="/referenz/spaltentypen">Spaltentypen-Referenz</a></li></ul>',30)])])}const g=n(i,[["render",l]]);export{c as __pageData,g as default};
